const WORD_BUCKETS = {};
{
  const seen = new Set();
  for (const raw of RAW_WORDS.trim().split(/\s+/)) {
    let word = raw.toLowerCase().replace(/ё/g, 'е');
    if (!/^[а-я]+$/.test(word)) continue;
    if (word.includes('ъ')) continue;
    if (word.length < 3 || word.length > 10) continue;
    if (seen.has(word)) continue;
    seen.add(word);
    (WORD_BUCKETS[word.length] ||= []).push(word);
  }
}

